// The production surfaces' right-click contract: the Studio's scenes, assets
// and providers, the Airtable instance cards, and the analytics tables.
//
// The one that matters most here is the asset card: an asset registered from a
// watched folder was never generated by this farm, so "make it again", "vary"
// and "say what was wrong" have nothing to act on. The row says so, and the
// menu is built from what it says — not from what the card happens to draw.
const fs = require('fs');
const path = require('path');

let pass = 0, fail = 0;
const ok = (n, c) => { if (c) { pass++; } else { fail++; console.log('  FAIL ' + n); } };

const { runPage } = require(path.join(__dirname, 'lib_page_dom.js'));
const NOW = Date.now();

// ============================================================ STUDIO
{
    const p = runPage('studio.js', {
        tab: 'pipeline', project: 'prod1',
        productions: [{
            id: 'prod1', title: 'The launch film', agentName: 'dev', file: 'D:/a/production.json',
            cost: 2, summary: '3 scenes', progress: { approved: 1, total: 3, percent: 33 },
            scenes: [
                { id: 'sc1', title: 'Opening', status: 'review', next: 'review', total: 2, counts: { image: 2, video: 0, audio: 0 }, untriaged: 1, thumbs: [] },
                { id: 'sc2', title: 'Middle', status: 'draft', next: 'generate', total: 0, counts: { image: 0, video: 0, audio: 0 }, untriaged: 0, thumbs: [] }
            ],
            unassigned: []
        }],
        items: [
            {
                taskId: 't1', title: 'shot A', kind: 'image', model: 'flux', ts: NOW - 1000,
                assetPath: 'D:/m/a.png', assetUri: '', source: 'workflow', projectId: 'prod1',
                sceneId: 'sc1', input: 'a wide shot', estCost: 0.02, selectedCount: 0, rejectedCount: 0
            },
            {
                taskId: 't2', title: 'dropped-in clip', kind: 'video', model: '', ts: NOW - 2000,
                assetPath: 'D:/m/b.mp4', assetUri: '', source: 'external:watched', projectId: 'prod1',
                sceneId: 'sc1', input: '', estCost: 0, selectedCount: 0, rejectedCount: 0
            }
        ],
        providers: { fal: true, replicate: false },
        cost: { today: 0, month: 0, total: 0, budgetMonth: 0 },
        ingestFolders: []
    });

    ok('the Studio renders its pipeline', p.html().includes('Opening'));
    const sc = p.contexts().find(c => c.webviewSection === 'afSceneRow' && c.sceneId === 'sc1');
    ok('a scene publishes what it is and what it is waiting for',
        !!sc && sc.sceneStatus === 'review' && sc.sceneNext === 'review');

    p.posted.length = 0;
    p.send({ type: 'afctx', act: 'scStatus:approved', ctx: sc });
    ok('‼️ the menu names the status outright — the badge only opens a picker',
        p.last().type === 'setSceneStatus' && p.last().sceneId === 'sc1' && p.last().status === 'approved');

    const gen = p.contexts().find(c => c.webviewSection === 'afSceneRow' && c.sceneId === 'sc2');
    p.send({ type: 'afctx', act: 'scNext', ctx: gen });
    ok('"do the next thing" runs whatever the row\'s own button runs',
        p.last().type === 'generate' && p.last().sceneId === 'sc2');
    p.send({ type: 'afctx', act: 'scAssets', ctx: sc });
    ok('…and "show its assets" scopes the Assets tab to it',
        p.last().type === 'tab' && p.last().tab === 'assets');

    // The asset wall.
    const tabBtn = p.query('[data-tab="assets"]')[0];
    if (tabBtn) { tabBtn.click(); }
    p.send({ type: 'data', data: Object.assign({}, p.sandbox.window.__DATA__, { tab: 'assets' }) });
    const made = p.contexts().find(c => c.webviewSection === 'afAssetCard' && c.asTask === 't1');
    const found = p.contexts().find(c => c.webviewSection === 'afAssetCard' && c.asTask === 't2');
    ok('an asset publishes its task, its file and what made it',
        !!made && made.asPath === 'D:/m/a.png' && made.asModel === 'flux' && made.asExternal === false);
    ok('‼️ one registered from a watched folder says it was NOT generated here',
        !!found && found.asExternal === true);

    p.posted.length = 0;
    p.send({ type: 'afctx', act: 'asRerun', ctx: made });
    ok('making it again names its task', p.last().type === 'rerun' && p.last().taskId === 't1');
    p.send({ type: 'afctx', act: 'asTriage:1', ctx: made });
    ok('‼️ keeping it is reachable here — the verdict lived on another tab entirely',
        p.last().type === 'triageDecision' && p.last().keep === true && p.last().taskId === 't1');
    p.send({ type: 'afctx', act: 'asTriage:0', ctx: found });
    ok('…and so is dropping it', p.last().type === 'triageDecision' && p.last().keep === false);

    // Who generates.
    const srcBtn = p.query('[data-tab="sources"]')[0];
    if (srcBtn) { srcBtn.click(); }
    p.send({ type: 'data', data: Object.assign({}, p.sandbox.window.__DATA__, { tab: 'sources' }) });
    const prov = p.contexts().find(c => c.webviewSection === 'afProviderRow');
    ok('a provider publishes its name and its setting',
        !!prov && !!prov.pvName && prov.pvSetting.indexOf('agentFarm.') === 0);
    p.posted.length = 0;
    p.send({ type: 'afctx', act: 'pvSetting', ctx: prov });
    ok('its setting opens at that key',
        p.last().type === 'openSettings' && p.last().focus === prov.pvSetting);
    p.send({ type: 'afctx', act: 'pvVault', ctx: prov });
    ok('…and the vault, which is where the key actually lives',
        p.last().type === 'afnav' && p.last().to === 'secrets');
}

// ============================================================ AIRTABLE
{
    const p = runPage('airtablePage.js', {
        generatedAt: NOW,
        store: { databaseRoots: [], mediaRoots: [], defaultInstance: 'main', defaultLang: 'TR', requestTimeoutMs: 8000 },
        expandedRoots: [],
        registration: { registered: true, upToDate: true, currentPath: 'D:/z/index.js', configFile: 'D:/z/.claude.json', current: {} },
        staging: { dir: 'D:/z/mcp', version: '1.0.0', extensionVersion: '1.0.0' },
        configFile: 'D:/z/airtable.json', configFileToken: 'airtable.json',
        probe: { ok: true, tools: [], probedAt: NOW },
        instances: [
            { name: 'main', dir: 'D:/z/main', host: 'localhost', port: 8801, url: 'http://localhost:8801', alive: true, isDefault: true, title: 'Main base', stats: {} },
            { name: 'spare', dir: 'D:/z/spare', host: 'localhost', port: 8802, url: '', alive: false, isDefault: false, error: 'not running' }
        ]
    });

    ok('the page renders its instance cards', p.html().includes('main') && p.html().includes('spare'));
    const dflt = p.contexts().find(c => c.webviewSection === 'afAirtableInstance' && c.instName === 'main');
    const other = p.contexts().find(c => c.webviewSection === 'afAirtableInstance' && c.instName === 'spare');
    ok('an instance publishes its name, its folder and whether it is the default',
        !!dflt && dflt.instDir === 'D:/z/main' && dflt.afDefault === true);
    ok('‼️ the default one is not offered "make it the default"', !!other && other.afDefault === false);

    p.posted.length = 0;
    p.send({ type: 'afctx', act: 'atDefault', ctx: other });
    ok('making one the default is the row button\'s own message',
        p.last().type === 'set' && p.last().key === 'defaultInstance' && p.last().value === 'spare');
    p.send({ type: 'afctx', act: 'atReveal', ctx: other });
    ok('revealing it uses the path the CARD carries',
        p.last().type === 'reveal' && p.last().path === 'D:/z/spare');
}

// ============================================================ ANALYTICS
{
    const pkg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '..', 'package.json'), 'utf8'));
    const web = pkg.contributes.menus['webview/context'];
    const onTable = web.filter(e => e.when === "webviewSection == 'afAnalyticsTable'").map(e => e.command);
    ok('an analytics TABLE has a menu', onTable.length >= 3);
    ok('…including the task history, which is a host command',
        onTable.indexOf('agentfarm.openTaskHistory') >= 0);
    // ‼️ Rows here are aggregates with no id; a row menu would have to invent one.
    ok('‼️ there is no afAnalyticsRow section — the rows carry nothing to act on',
        !web.some(e => String(e.when || '').includes('afAnalyticsRow')));
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
